package dev.codex.lastzhelper;
import java.io.*;import java.util.*;import org.json.*;
/** Read-only training template/cost inventory; capacity and spending remain unresolved. */
final class TrainingStartReader {
 static JSONObject read(String cache,String uid)throws Exception{
  JSONObject queues=TrainingReader.read(cache);if(!uid.equals(queues.getString("accountUid")))throw new IOException("Training inspection account changed");
  try(GameMemory m=new GameMemory(cache)){
   BaseBubbleReader.context(m,uid);Map<Integer,JSONObject> own=new HashMap<>();JSONArray queueRows=queues.getJSONArray("queues");
   for(int i=0;i<queueRows.length();i++){JSONObject q=queueRows.getJSONObject(i);long build=m.path("DataCenter/BuildManager/allBuilding/#"+q.getString("buildingUid"));if(!Long.toString(BaseBubbleReader.integer(build,"uuid")).equals(q.getString("buildingUid"))||BaseBubbleReader.integer(build,"itemId")!=q.getInt("buildingId")||BaseBubbleReader.bool(build,"isWorldBuild"))throw new IOException("Own training building changed");int type=q.getInt("type");if(own.containsKey(type))throw new IOException("Ambiguous own training building");own.put(type,new JSONObject().put("buildingUid",q.getString("buildingUid")).put("buildingId",q.getInt("buildingId")).put("level",BaseBubbleReader.integer(build,"level")).put("unlock",BaseBubbleReader.integer(build,"unlock")).put("lockInput",BaseBubbleReader.bool(build,"lockInput")).put("queueState",q.getInt("state")));}
   List<TruckDiscoveryProbe.Value> templates=BaseBubbleReader.rows(m.path("DataCenter/ArmyTemplateManager/armyTemplateDic"),512);JSONArray rows=new JSONArray();
   for(TruckDiscoveryProbe.Value entry:templates){
    StateProbe.cancelCheck();if(!entry.key.matches("#107[012][0-9]{2}"))continue;if((entry.tag&15)!=5)throw new IOException("Invalid unit template row");String id=entry.key.substring(1);long template=entry.raw;if(!Long.toString(BaseBubbleReader.integer(template,"id")).equals(id))throw new IOException("Unit template ID mismatch");int type=TrainingStartPolicy.type(id);long building=BaseBubbleReader.integer(template,"buildId");if(building!=TrainingPolicy.building(type))throw new IOException("Unit family/building mismatch");JSONObject owned=own.get(type);if(owned==null)throw new IOException("Unit template has no joined own building");JSONArray requirements=new JSONArray(),costs=new JSONArray();boolean allBuildMet=true;
    for(TruckDiscoveryProbe.Value r:BaseBubbleReader.rows(GameMemory.f(template,"unlock_train_build"),16)){if((r.tag&15)!=5)throw new IOException("Invalid training build requirement");long requiredBuild=BaseBubbleReader.integer(r.raw,"buildId"),requiredLevel=BaseBubbleReader.integer(r.raw,"level");String status=TrainingStartPolicy.buildingRequirement(owned.getLong("buildingId"),requiredBuild,owned.getLong("level"),requiredLevel);if(!status.equals("MET"))allBuildMet=false;requirements.put(new JSONObject().put("buildingId",requiredBuild).put("level",requiredLevel).put("decision",status));}
    int scienceRows=BaseBubbleReader.rows(GameMemory.f(template,"unlock_train_science"),64).size(),itemRows=BaseBubbleReader.rows(GameMemory.f(template,"needItem"),64).size();
    for(TruckDiscoveryProbe.Value r:BaseBubbleReader.rows(GameMemory.f(template,"needResource"),16)){if((r.tag&15)!=5)throw new IOException("Invalid unit resource cost");long resource=BaseBubbleReader.integer(r.raw,"resourceType"),count=BaseBubbleReader.integer(r.raw,"count");if(!TrainingStartPolicy.validCost(resource,count))throw new IOException("Invalid resource cost value");costs.put(new JSONObject().put("resourceType",resource).put("templateCountText",Long.toString(count)));}
    rows.put(new JSONObject().put("unitId",id).put("templateLevel",BaseBubbleReader.integer(template,"level")).put("type",type).put("ownBuilding",owned).put("buildRequirements",requirements).put("allObservedBuildRequirementsMet",requirements.length()>0&&allBuildMet).put("scienceRequirementRows",scienceRows).put("itemCostRows",itemRows).put("resourceCostTemplates",costs).put("timeTemplateRawText",Long.toString(BaseBubbleReader.integer(template,"time"))).put("maxTrainTemplateRawText",Long.toString(BaseBubbleReader.integer(template,"max_train"))).put("unlockedProven",false).put("capacityProven",false).put("costUnitsAndBonusesProven",false).put("startEnabled",false));
   }
   StateProbe.verifyPinned();BaseBubbleReader.context(m,uid);return new JSONObject().put("accountUid",uid).put("readOnly",true).put("memoryOnly",true).put("startEnabled",false).put("completeUnitCatalogProven",false).put("highestUnlockedTierProven",false).put("atomicSnapshot",false).put("infrastructureCacheMayRefresh",true).put("units",rows);
  }
 }
}
